<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class StockHistory extends Model {protected $fillable=['product_id','user_id','occurred_at','quantity_in','quantity_out','balance','activity','reference_type','reference_id']; protected $casts=['occurred_at'=>'datetime']; public function product(){return $this->belongsTo(Product::class)->withTrashed();} public function user(){return $this->belongsTo(User::class);}}
